<template><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="mb-1">Branches & stock transfers</h4><div class="text-muted small">Create branches and transfer batch-tracked inventory between them.</div></div><button class="btn btn-primary" @click="showBranch=!showBranch">Add branch</button></div>
<div v-if="showBranch" class="card mb-3"><form class="card-body row g-2" @submit.prevent="createBranch"><div class="col-md-4"><input v-model="branch.name" class="form-control" placeholder="Branch name" required></div><div class="col-md-3"><input v-model="branch.code" class="form-control" placeholder="Unique code" required></div><div class="col-md-3"><input v-model="branch.phone" class="form-control" placeholder="Phone"></div><div class="col-md-2"><button class="btn btn-primary w-100">Save branch</button></div><div class="col-12"><input v-model="branch.address" class="form-control" placeholder="Address"></div></form></div>
<div class="row g-3"><div class="col-lg-5"><div class="card h-100"><div class="card-header fw-semibold">Branches</div><div class="list-group list-group-flush"><div v-for="b in branches" :key="b.id" class="list-group-item d-flex justify-content-between"><span><b>{{b.name}}</b><small class="text-muted d-block">ID {{b.id}} · {{b.code}} · {{b.phone||'No phone'}}</small></span><span class="badge bg-success">Active</span></div></div></div></div>
<div class="col-lg-7"><div class="card"><div class="card-header fw-semibold">Request stock transfer</div><form class="card-body row g-2" @submit.prevent="createTransfer"><div class="col-md-6"><label class="form-label">From branch</label><select v-model.number="transfer.from_branch_id" class="form-select" required @change="loadStock"><option value="">Select</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div class="col-md-6"><label class="form-label">To branch</label><select v-model.number="transfer.to_branch_id" class="form-select" required><option value="">Select</option><option v-for="b in branches.filter(x=>x.id!==transfer.from_branch_id)" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div class="col-md-8"><label class="form-label">Source batch</label><select v-model.number="transfer.items[0].source_batch_id" class="form-select" required><option value="">Select batch</option><option v-for="b in batches" :key="b.id" :value="b.id">{{b.medicine?.name}} · {{b.batch_no||'No batch'}} · {{b.quantity}} units</option></select></div><div class="col-md-4"><label class="form-label">Quantity (units)</label><input v-model.number="transfer.items[0].quantity" type="number" min="1" class="form-control" required></div><div class="col-12"><input v-model="transfer.notes" class="form-control" placeholder="Transfer note"></div><div class="col-12 text-end"><button class="btn btn-primary">Submit transfer request</button></div></form></div></div></div>
<div class="card mt-3"><div class="card-header fw-semibold">Transfer history</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Transfer</th><th>From</th><th>To</th><th>Status</th><th class="text-end">Action</th></tr></thead><tbody><tr v-for="t in transfers" :key="t.id"><td>{{t.transfer_no}}</td><td>{{t.from_branch?.name}}</td><td>{{t.to_branch?.name}}</td><td><span class="badge bg-secondary">{{t.status}}</span></td><td class="text-end"><button v-if="t.status==='pending'" class="btn btn-sm btn-primary" @click="review(t)">Approve & transfer</button></td></tr></tbody></table></div></div></div></template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import api from '../api';import {Swal} from '../utils/swal';const branches=ref([]),transfers=ref([]),batches=ref([]),showBranch=ref(false);const branch=reactive({name:'',code:'',phone:'',address:''});const transfer=reactive({from_branch_id:'',to_branch_id:'',notes:'',items:[{source_batch_id:'',quantity:1}]});async function load(){const [b,t]=await Promise.all([api.get('/branches'),api.get('/branch-transfers')]);branches.value=b.data;transfers.value=t.data.data||[];}async function createBranch(){await api.post('/branches',branch);Object.assign(branch,{name:'',code:'',phone:'',address:''});showBranch.value=false;await load();}async function loadStock(){if(!transfer.from_branch_id)return;batches.value=(await api.get('/branch-stock',{params:{branch_id:transfer.from_branch_id,per_page:100}})).data.data||[];}async function createTransfer(){await api.post('/branch-transfers',transfer);transfer.items=[{source_batch_id:'',quantity:1}];await load();}async function review(t){const r=await Swal.fire({title:'Approve stock transfer?',text:'This immediately deducts the source batch and creates a destination batch.',icon:'warning',showCancelButton:true,confirmButtonText:'Approve transfer'});if(!r.isConfirmed)return;await api.post(`/branch-transfers/${t.id}/review`,{decision:'approve'});await load();}onMounted(load);
</script>
